export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

interface ErasureRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  created_at: Date;
  updated_at: Date;
