}

export interface ErasureRequest {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: Date;
  updatedAt: Date;
  completedAt: Date | null;
  lastError: string | null;
}

function present(row: ErasureRow): ErasureRequest {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async createOrResume(merchantId: string, customerId: string, key: string): Promise<ErasureRequest> {
    return await transaction(async (client) => {
      await advisoryLock(client, `customer-erasure:${merchantId}:${customerId}`);
      const replay = await client.query<ErasureRow & { keyed_customer_id: string }>(
        `SELECT r.*,k.customer_id keyed_customer_id
         FROM customers.erasure_idempotency_keys k
         JOIN customers.erasure_requests r ON r.id=k.request_id
         WHERE k.merchant_id=$1 AND k.key=$2`,
        [merchantId, key],
      );
      if (replay.rows[0]) {
        if (replay.rows[0].keyed_customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
        }
        return present(await this.resumeFailed(client, replay.rows[0]));
      }

      const customer = await client.query(
        `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customer.rowCount) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

      const request = await client.query<ErasureRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id)
         VALUES($1,$2)
         ON CONFLICT(merchant_id,customer_id) DO UPDATE SET updated_at=customers.erasure_requests.updated_at
         RETURNING *`,
        [merchantId, customerId],
      );
      const row = await this.resumeFailed(client, request.rows[0]!);
      await client.query(
        `INSERT INTO customers.erasure_idempotency_keys(merchant_id,key,customer_id,request_id)
         VALUES($1,$2,$3,$4)`,
        [merchantId, key, customerId, row.id],
      );
      await client.query(
        `UPDATE customers.customers SET status='erasure_pending',updated_at=now()
         WHERE merchant_id=$1 AND id=$2 AND status<>'erased'`,
        [merchantId, customerId],
      );
      return present(row);
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequest | undefined> {
    const result = await pool.query<ErasureRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0] ? present(result.rows[0]) : undefined;
  }

  async recoverInterrupted(): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error='processing_interrupted',updated_at=now(),locked_by=NULL,locked_at=NULL
       WHERE status='processing' AND locked_at<now()-interval '5 minutes'`,
    );
  }

  async claim(workerId: string): Promise<ErasureRow | undefined> {
    const result = await pool.query<ErasureRow>(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,updated_at=now(),locked_by=$1,locked_at=now()
       WHERE id=(SELECT id FROM customers.erasure_requests WHERE status='pending'
         ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING *`,
      [workerId],
    );
    return result.rows[0];
  }

  async fail(id: string, code: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests SET status='failed',last_error=$2,updated_at=now(),locked_by=NULL,locked_at=NULL
       WHERE id=$1 AND status='processing'`,
      [id, code],
    );
  }

  private async resumeFailed(client: PoolClient, row: ErasureRow): Promise<ErasureRow> {
    if (row.status !== 'failed') return row;
    const resumed = await client.query<ErasureRow>(
      `UPDATE customers.erasure_requests
       SET status='pending',last_error=NULL,updated_at=now(),locked_by=NULL,locked_at=NULL
       WHERE id=$1 RETURNING *`,
      [row.id],
    );
    return resumed.rows[0]!;
  }
}

export class ErasureProcessor {
  async process(request: ErasureRow): Promise<void> {
    await transaction(async (client) => {
      await advisoryLock(client, `customer-erasure:${request.merchant_id}:${request.customer_id}`);
      const current = await client.query<{ status: ErasureStatus }>(
        `SELECT status FROM customers.erasure_requests WHERE id=$1 FOR UPDATE`,
        [request.id],
      );
      if (current.rows[0]?.status !== 'processing') return;
      await this.removeObjects(client, request.merchant_id, request.customer_id);
      await this.scrubDatabase(client, request.merchant_id, request.customer_id);
      await client.query(
        `UPDATE customers.erasure_requests
         SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL,locked_by=NULL,locked_at=NULL
         WHERE id=$1`,
        [request.id],
      );
    });
  }

  private async removeObjects(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    const result = await client.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2
